---@referenceName scene_sheep_sound.lua
local U=CS.UnityEngine
local function makeClip(name,duration,fn)
 local rate=22050;local samples={};local count=math.floor(rate*duration)
 for i=1,count do samples[i]=fn((i-1)/rate) end
 local clip=U.AudioClip.Create(name,count,1,rate,false);clip:SetData(samples,0);return clip
end
local baa=nil
local source=nil
local nextCall=0
function Start()
 local bytes=CS.System.Convert.FromBase64String("")
 local samples={}
 for i=1,#bytes,2 do local v=string.byte(bytes,i)+string.byte(bytes,i+1)*256;if v>=32768 then v=v-65536 end;samples[#samples+1]=v/32768 end
 baa=U.AudioClip.Create("sheep_real_earthcalling",130983,1,16000,false);baa:SetData(samples,0)
 source=self.gameObject:AddComponent(typeof(U.AudioSource))
 source.playOnAwake=false;source.loop=false;source.spatialBlend=.35
 source.minDistance=4;source.maxDistance=18;source.volume=.95
end
function OnActorTriggerEnter(actor)
 if not actor or not actor.isLocal or not source then return end
 local now=U.Time.time
 if now<nextCall or now<U.Shader.GetGlobalFloat('_DragonNextBaa') or not baa then return end
 nextCall=now+14;U.Shader.SetGlobalFloat('_DragonNextBaa',now+5);source:PlayOneShot(baa)
end
function Update()
 local actor=DouyinActorService.GetLocalActor()
 if actor and U.Vector3.Distance(actor.position,self.transform.position)<4.5 then OnActorTriggerEnter(actor) end
end
function OnDestroy()
 if source then U.Object.Destroy(source);source=nil end
 if baa then U.Object.Destroy(baa) end
end
